/* SF-101: public directory aggregates; never use private alliance intel or profiles. */
let universeAllianceSection='overview',universeAllianceSelection='',universeAllianceContext='';
function universeAllianceNumber(value){return typeof value==='number'&&Number.isSafeInteger(value)&&value>=0?value:null;}
function universeAllianceEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function universeAllianceGroups(snapshot){
 const groups=new Map(),seen=new Set();for(const p of snapshot.galaxy||[]){if(!p||!p.id||seen.has(p.id)||p.structurePlanet||p.ghostPlanet||p.dummy)continue;seen.add(p.id);const name=typeof p.alliance==='string'?p.alliance.trim():'';if(!name||name==='Unaffiliated')continue;
 const values=p.player?{score:typeof playerScore==='function'?universeAllianceNumber(playerScore()):universeAllianceNumber(p.publicScore),roids:typeof totalRoids==='function'?universeAllianceNumber(totalRoids(snapshot.roids||{})):null,population:universeAllianceNumber(snapshot.population),xp:universeAllianceNumber(snapshot.xp)}:{score:universeAllianceNumber(p.publicScore),roids:universeAllianceNumber(p.publicSize),population:universeAllianceNumber(p.publicPopulation),xp:universeAllianceNumber(p.publicXP)};
 const group=groups.get(name)||{name,members:[],totals:{score:0,roids:0,population:0,xp:0},reported:{score:0,roids:0,population:0,xp:0}};group.members.push({id:String(p.id),ruler:String(p.ruler||'Not reported'),planet:String(p.name||'Not reported'),coords:String(p.coords||''),exiled:!!p.exiled,...values});for(const key of Object.keys(values))if(values[key]!==null){group.totals[key]+=values[key];group.reported[key]++;}groups.set(name,group);
 }
 return [...groups.values()].sort((a,b)=>b.totals.score-a.totals.score||a.name.localeCompare(b.name));
}
function universeAllianceMetric(group,key){const count=group.reported[key],all=group.members.length;if(!count)return '—';return group.totals[key].toLocaleString('en-US')+(count<all?' *':'');}
function universeAllianceTableHTML(groups){const e=universeAllianceEscape;return '<section class="panel universe-alliance-ranking"><div class="ph"><div class="pt">TOP 10 ALLIANCES</div><span class="meta">REPORTED PUBLIC SCORE</span></div><div class="table-wrap"><table class="table"><caption class="meta">Current directory membership · highest reported score first</caption><thead><tr><th scope="col">#</th><th scope="col">Alliance</th><th scope="col">Members</th><th scope="col">Asteroids</th><th scope="col">Score</th><th scope="col">Population</th><th scope="col">XP</th></tr></thead><tbody>'+groups.slice(0,10).map((g,i)=>'<tr><td>'+ (i+1)+'</td><th scope="row"><button class="btn" data-universe-alliance="'+e(g.name)+'">'+e(g.name)+'</button></th><td>'+g.members.length+'</td><td>'+universeAllianceMetric(g,'roids')+'</td><td>'+universeAllianceMetric(g,'score')+'</td><td>'+universeAllianceMetric(g,'population')+'</td><td>'+universeAllianceMetric(g,'xp')+'</td></tr>').join('')+(groups.length?'':'<tr><td colspan="7" class="empty">No affiliated planets are recorded in the current directory.</td></tr>')+'</tbody></table></div><p class="universe-module-note">* Partial total: some members have not reported this value. Missing measurements are shown as —. Rankings use the latest public reports, which may come from different ticks.</p></section>';}
function universeAllianceDetailHTML(groups,selected){const e=universeAllianceEscape,group=groups.find(g=>g.name===selected)||groups[0];if(!group)return '';const value=n=>n===null?'—':n.toLocaleString('en-US');return '<section class="panel universe-alliance-detail"><div class="ph"><div class="pt">ALLIANCE DETAIL</div><span class="meta">PUBLIC DIRECTORY ONLY</span></div><div class="controls"><div class="field"><label for="universeAllianceSelect">Alliance</label><select id="universeAllianceSelect">'+groups.map(g=>'<option value="'+e(g.name)+'" '+(g===group?'selected':'')+'>'+e(g.name)+'</option>').join('')+'</select></div></div><h3 style="margin:8px 12px">'+e(group.name)+'</h3><div class="alliance-kpis">'+[['Members',group.members.length],['Asteroids',universeAllianceMetric(group,'roids')],['Score',universeAllianceMetric(group,'score')],['Population',universeAllianceMetric(group,'population')],['XP',universeAllianceMetric(group,'xp')]].map(([label,n])=>'<div class="alliance-kpi"><small>'+label+'</small><b>'+n+'</b></div>').join('')+'</div><div class="table-wrap"><table class="table"><caption class="meta">Members and latest public measurements</caption><thead><tr><th scope="col">Ruler</th><th scope="col">Planet</th><th scope="col">Coordinates</th><th scope="col">Asteroids</th><th scope="col">Score</th><th scope="col">Population</th><th scope="col">XP</th></tr></thead><tbody>'+[...group.members].sort((a,b)=>(b.score??-1)-(a.score??-1)||a.ruler.localeCompare(b.ruler)).map(p=>'<tr><th scope="row">'+e(p.ruler)+'</th><td>'+e(p.planet)+(p.exiled?' <small>EXILED</small>':'')+'</td><td>'+e(p.coords)+'</td><td>'+value(p.roids)+'</td><td>'+value(p.score)+'</td><td>'+value(p.population)+'</td><td>'+value(p.xp)+'</td></tr>').join('')+'</tbody></table></div><p class="universe-module-note">Reported members: score '+group.reported.score+'/'+group.members.length+' · asteroids '+group.reported.roids+'/'+group.members.length+' · population '+group.reported.population+'/'+group.members.length+' · XP '+group.reported.xp+'/'+group.members.length+'. Exiled members remain included while their directory membership remains unchanged. Private scans, ranks, reserves and intelligence notes are not used.</p></section>';}
function renderUniverseAlliances(){
 const page=document.getElementById('page-universe');if(!page)return;const context=[state.centralPlayerId||'',state.centralResetGeneration||0].join(':');if(context!==universeAllianceContext){universeAllianceContext=context;universeAllianceSelection='';universeAllianceSection='overview';}
 let existing=document.getElementById('universePlanetView'),board=document.getElementById('universeAllianceView'),nav=document.getElementById('universeSectionTabs');if(!existing){existing=document.createElement('div');existing.id='universePlanetView';for(const child of [...page.children])if(!child.classList.contains('hero'))existing.append(child);page.append(existing);}
 if(!nav){nav=document.createElement('nav');nav.id='universeSectionTabs';nav.className='alliance-tabs';nav.setAttribute('aria-label','Universe sections');nav.innerHTML='<button data-universe-section="overview">Total overview</button><button data-universe-section="planets">Planets & statistics</button><button data-universe-section="alliances">Alliances</button>';page.insertBefore(nav,existing);}
 if(!board){board=document.createElement('div');board.id='universeAllianceView';board.className='universe-alliances-view';board.style.cssText='display:grid;gap:12px;margin-top:12px;min-width:0';page.append(board);}
 const groups=universeAllianceGroups(state);if(!groups.some(g=>g.name===universeAllianceSelection))universeAllianceSelection=groups[0]?.name||'';board.innerHTML=universeAllianceTableHTML(groups)+universeAllianceDetailHTML(groups,universeAllianceSelection);existing.hidden=universeAllianceSection==='alliances';board.hidden=universeAllianceSection==='planets';board.style.display=board.hidden?'none':'grid';for(const button of nav.querySelectorAll('[data-universe-section]')){const selected=button.dataset.universeSection===universeAllianceSection;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));}
}
const universeDirectoryRender=renderUniverse;renderUniverse=function(){universeDirectoryRender();renderUniverseAlliances();};
const universeDirectoryNavigate=navigate;navigate=function(page){const result=universeDirectoryNavigate(page);if(page==='universe')renderUniverse();return result;};
document.addEventListener('click',event=>{const section=event.target.closest?.('[data-universe-section]'),alliance=event.target.closest?.('[data-universe-alliance]');if(section&&['overview','planets','alliances'].includes(section.dataset.universeSection)){universeAllianceSection=section.dataset.universeSection;renderUniverseAlliances();}if(alliance){universeAllianceSelection=alliance.dataset.universeAlliance;renderUniverseAlliances();document.querySelector('.universe-alliance-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'});}});
document.addEventListener('change',event=>{if(event.target.id==='universeAllianceSelect'){universeAllianceSelection=event.target.value;renderUniverseAlliances();document.getElementById('universeAllianceSelect')?.focus({preventScroll:true});}});
